#define PI acos(-1.)
#define TAU PI*2.
#define rot(a) mat2(cos(a + vec4(0,33,11,0)))
#define t iTime

// From https://www.shadertoy.com/view/Xl2yDW
float sdEquilateralTriangle( in vec2 p )
{
    const float k = sqrt(3.0);
    p.x = abs(p.x) - 1.0;
    p.y = p.y + 1.0/k;
    if( p.x+k*p.y>0.0 ) p = vec2(p.x-k*p.y,-k*p.x-p.y)/2.0;
    p.x -= clamp( p.x, -2.0, 0.0 );
    return -length(p)*sign(p.y);
}

// From https://www.shadertoy.com/view/fdBcR3
float SDF_SierpinskiTriangle(vec2 p, uint n) // by jt
{
    vec3 q =
        vec3 // global coordinates (barycentric)
        (
            (-sqrt(3.0)*p.y-3.0*p.x+1.0)/3.0,
            (-sqrt(3.0)*p.y+3.0*p.x+1.0)/3.0,
            (2.0*sqrt(3.0)*p.y+1.0)/3.0
        );

    if(any(lessThan(q, vec3(0.0))))
        return sdEquilateralTriangle(p * 2.0) / 2.0;

    float N = exp2(float(n));
    q = 1.0 - q;
    ivec3 i = ivec3(q * N);
    int f = i.x & i.y & i.z;
    if(f == 0)
    {
        q = 1.0 - q;
        q = mod(q, 1.0 / N);
        return -min(min(q.x, q.y), q.z); // correct: base-case is interior
        //return min(min(q.x, q.y), q.z); // ...but this looks nicer in the visualization
    }
    float s = exp2(floor(log2(float(f)))) * 2.0 / N;

    q = mod(q * 2.0, s) / 2.0 * sqrt(3.0) / 2.0; // local coordinates (barycentric)

    return min(min(q.x, q.y), q.z); // correct: triangle has only outside...
    //return -min(min(q.x, q.y), q.z); // ...but this looks nicer in the visualization
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec3 col;

    vec2 uv = (fragCoord -.5* iResolution.xy) / iResolution.y;



    float n = 1.+7.*abs(sin(t));
    float h = .0015;
    float dtot;

    for (float i; i<7.; i+=.1)
    {
        uv/=1.-uv.y*1.55;
          uv.xy*=mat2(cos(iTime),sin(iTime),-sin(iTime),cos(iTime));
        float a = radians(360./7.) * i;
        vec2 p = uv;



        float d = SDF_SierpinskiTriangle(p, uint(n));
        d = h/abs(d);
        dtot += d;

        h /= 1.1;

        col += d;
    }

    col += dtot;
    col /= n;
    fragColor = vec4(col*vec3(0.2,1.,2.), 1.);
}
